const html = $input.first().json.html;

const buffer = Buffer.from(html, 'utf-8');

return [
  {
    json: {},
    binary: {
      data: await this.helpers.prepareBinaryData(
        buffer,
        'ata-reuniao.html',
        'text/html'
      )
    }
  }
];

const item = $input.first();

item.binary.data.fileName = 'ata-reuniao.pdf';
item.binary.data.fileExtension = 'pdf';
item.binary.data.mimeType = 'application/pdf';

return [item];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const dados = $input.first().json.output;

const participantes = Array.isArray(dados.participantes)
  ? dados.participantes
  : [];

const escapeHtml = (text) => {
  if (text === null || text === undefined) return '';

  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};

const decisoes = Array.isArray(dados.decisoes)
  ? dados.decisoes
  : [];

const tarefas = Array.isArray(dados.tarefas)
  ? dados.tarefas
  : [];

const pendencias = Array.isArray(dados.pendencias)
  ? dados.pendencias
  : [];

const decisoesHtml = decisoes.length
  ? decisoes
      .map(decisao => `<li>${escapeHtml(decisao)}</li>`)
      .join('')
  : '<li class="empty">Nenhuma decisão registrada.</li>';

const tarefasHtml = tarefas.length
  ? tarefas
      .map(tarefa => `
        <tr>
          <td>${escapeHtml(tarefa.tarefa)}</td>
          <td>${escapeHtml(tarefa.responsavel)}</td>
          <td>${escapeHtml(tarefa.prazo)}</td>
        </tr>
      `)
      .join('')
  : `
      <tr>
        <td colspan="3" class="empty">Nenhuma tarefa registrada.</td>
      </tr>
    `;

const pendenciasHtml = pendencias.length
  ? pendencias
      .map(pendencia => `<li>${escapeHtml(pendencia)}</li>`)
      .join('')
  : '<li class="empty">Nenhuma pendência registrada.</li>';

const participantesHtml = participantes.length
  ? participantes.map(nome => `<li>${nome}</li>`).join('')
  : '<li class="empty">Não identificados.</li>';

const html = `
<!DOCTYPE html>
<html lang="pt">
<head>
  <meta charset="UTF-8">

  <meta name="viewport" content="width=device-width, initial-scale=1.0">

  <title>Ata da Reunião</title>

  <style>
    * {
      box-sizing: border-box;
    }

    body {
      font-family: Arial, Helvetica, sans-serif;
      background: #f4f6f8;
      color: #2d3748;
      margin: 0;
      padding: 40px 20px;
      line-height: 1.6;
    }

    .document {
      max-width: 900px;
      margin: 0 auto;
      background: #ffffff;
      padding: 50px 60px;
      border-radius: 8px;
      box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
    }

    .header {
      text-align: center;
      border-bottom: 2px solid #e2e8f0;
      padding-bottom: 25px;
      margin-bottom: 35px;
    }

    .header h1 {
      margin: 0;
      font-size: 28px;
      letter-spacing: 1px;
    }

    .header .subtitle {
      margin-top: 8px;
      font-size: 16px;
      color: #718096;
    }

    section {
      margin-bottom: 35px;
    }

    h2 {
      font-size: 18px;
      margin-bottom: 12px;
      padding-bottom: 8px;
      border-bottom: 1px solid #e2e8f0;
    }

    .summary {
      text-align: justify;
    }

    ul {
      margin: 0;
      padding-left: 22px;
    }

    li {
      margin-bottom: 8px;
    }

    table {
      width: 100%;
      border-collapse: collapse;
      margin-top: 15px;
    }

    th,
    td {
      padding: 12px;
      border-bottom: 1px solid #e2e8f0;
      text-align: left;
      vertical-align: top;
    }

    th {
      font-weight: bold;
      background: #f7fafc;
    }

    .empty {
      color: #718096;
      font-style: italic;
    }

    .footer {
      margin-top: 45px;
      padding-top: 15px;
      border-top: 1px solid #e2e8f0;
      text-align: center;
      font-size: 12px;
      color: #a0aec0;
    }

    @media print {
      body {
        background: #ffffff;
        padding: 0;
      }

      .document {
        box-shadow: none;
        max-width: none;
        padding: 30px;
      }
    }

    @media (max-width: 700px) {
      body {
        padding: 15px;
      }

      .document {
        padding: 30px 20px;
