      th,
      td {
        padding: 8px;
      }
    }
  </style>
</head>

<body>

  <main class="document">

    <header class="header">
      <h1>ATA DE REUNIÃO</h1>
    </header>

    <section>
      <h2>Participantes</h2>
      <ul>
        ${participantesHtml}
      </ul>
    </section>

    <section>
      <h2>Resumo</h2>
      <p class="summary">${escapeHtml(dados.resumo)}</p>
    </section>

    <section>
      <h2>Decisões tomadas</h2>
      <ul>
        ${decisoesHtml}
      </ul>
    </section>

    <section>
      <h2>Plano de ação</h2>

      <table>
        <thead>
          <tr>
            <th>Tarefa</th>
            <th>Responsável</th>
            <th>Prazo</th>
          </tr>
        </thead>

        <tbody>
          ${tarefasHtml}
        </tbody>
      </table>
    </section>

    <section>
      <h2>Pendências</h2>
      <ul>
        ${pendenciasHtml}
      </ul>
    </section>

    <footer class="footer">
      Ata gerada automaticamente por AI Meeting Assistant
    </footer>

  </main>

</body>
</html>
`;

return [
  {
    json: {
      html
    }
  }
];
